import{_ as a,o,c as l,a2 as i}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"4.2 万用表","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-2-wan-yong-biao.md","filePath":"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-2-wan-yong-biao.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/4-2-wan-yong-biao.md"};function n(e,t,s,d,g,h){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_4-2-万用表" tabindex="-1">4.2 万用表 <a class="header-anchor" href="#_4-2-万用表" aria-label="Permalink to &quot;4.2 万用表&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>万用表(多用表)是电工最常用的仪表,<strong>一表多能</strong>:测电压、电流、电阻都能干。这一节讲清万用表的结构、怎么接、怎么测,以及最重要的<strong>安全注意事项</strong>——用错了轻则烧表,重则伤人。</p><h2 id="一、万用表能测什么" tabindex="-1">一、万用表能测什么 <a class="header-anchor" href="#一、万用表能测什么" aria-label="Permalink to &quot;一、万用表能测什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能挡</th><th>测量内容</th><th>说明</th></tr></thead><tbody><tr><td>直流电压挡</td><td>直流电压</td><td>注意正负极性</td></tr><tr><td>交流电压挡</td><td>交流电压</td><td>常用 220 V、380 V</td></tr><tr><td>直流电流挡</td><td>直流电流</td><td>电流表要串联</td></tr><tr><td>欧姆挡</td><td>电阻</td><td><strong>不能带电测量</strong></td></tr><tr><td>交流电流挡(部分型号)</td><td>交流电流</td><td>—</td></tr></tbody></table><blockquote><p>⚠️ 万用表最常测的是<strong>电压和电阻</strong>;测大电流一般用钳形表(4.3 节)更方便。</p></blockquote><h2 id="二、使用万用表的基本步骤" tabindex="-1">二、使用万用表的基本步骤 <a class="header-anchor" href="#二、使用万用表的基本步骤" aria-label="Permalink to &quot;二、使用万用表的基本步骤&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选挡 → 选量程 → 接入测量 → 读表 → 归零(拨到关闭或电压挡)</span></span></code></pre></div><ol><li><strong>选挡</strong>:先确定测的是电压、电流还是电阻,拨到对应挡位;</li><li><strong>选量程</strong>:先大后小,指针偏转在刻度 1/2~2/3 区域最准;</li><li><strong>接入</strong>: <ul><li>测<strong>电压</strong>:表笔与被测电路<strong>并联</strong>(红表笔接正极/火线,黑表笔接负极/零线);</li><li>测<strong>电流</strong>:表笔与被测电路<strong>串联</strong>(需断开电路串入);</li><li>测<strong>电阻</strong>:被测电阻<strong>断电</strong>后测量;</li></ul></li><li><strong>读表</strong>:读数乘以倍率(如欧姆挡 ×100);</li><li><strong>用完归零</strong>:把转换开关拨回<strong>交流电压最高挡</strong>或关闭挡,防止下次误用。</li></ol><h2 id="三、测电阻的特别要求" tabindex="-1">三、测电阻的特别要求 <a class="header-anchor" href="#三、测电阻的特别要求" aria-label="Permalink to &quot;三、测电阻的特别要求&quot;">​</a></h2><ol><li><strong>必须断电测量</strong>:严禁在带电设备上用欧姆挡测电阻,否则烧表;</li><li><strong>欧姆调零</strong>:每次换挡后,先把两表笔短接,调节&quot;欧姆调零旋钮&quot;使指针指向 0 Ω;</li><li>被测电阻两端不能与其他电路并联,否则读数不准。</li></ol><h2 id="四、安全注意事项-重点" tabindex="-1">四、安全注意事项(重点) <a class="header-anchor" href="#四、安全注意事项-重点" aria-label="Permalink to &quot;四、安全注意事项(重点)&quot;">​</a></h2><ul><li>❌ <strong>严禁用欧姆挡测量带电设备</strong>;</li><li>❌ 测量时<strong>手不能触碰表笔的金属端</strong>(带电时);</li><li>✅ 测电压前确认量程,防止小量程测大电压烧表;</li><li>✅ 测直流时极性接反,指针会反打,可能损坏表头;</li><li>✅ 在带电设备上测量,保持安全距离,穿绝缘鞋、戴绝缘手套。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 测电压<strong>并联</strong>、测电流<strong>串联</strong>、测电阻<strong>断电后测</strong>。</li><li>✅ 欧姆挡测电阻前要<strong>调零</strong>(短接表笔)。</li><li>✅ 严禁带电测电阻。</li><li>⚠️ 易混点:并联/串联别接反——电压表并联(跨接)、电流表串联(串入)。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>万用表:选挡→选量程→接入→读数→归零。</li><li>测电阻必须断电、要调零;测电压并联;测电流串联。</li><li>带电测电阻是禁忌,会烧表甚至伤人。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)用万用表欧姆挡可以带电测量电路中的电阻。( )</li><li>(单选)测量电压时,万用表应与被测电路()。 A. 串联　B. 并联　C. 串联并联均可　D. 不用接入</li><li>(判断)用欧姆挡测电阻前,应将两表笔短接并调节调零旋钮,使指针指到 0 Ω。( )</li><li>(单选)万用表用完应将转换开关拨回()。 A. 欧姆挡　B. 交流电压最高挡　C. 直流电压挡　D. 任意挡</li><li>(判断)万用表测电压时,红表笔应接被测电路的正极(或火线)。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>×</strong>。严禁带电测电阻,必须先断电。</li><li><strong>B</strong>。测电压并联(跨接),测电流串联(串入)。</li><li><strong>√</strong>。欧姆挡使用前要短接表笔调零。</li><li><strong>B</strong>。用完拨回交流电压最高挡或关闭挡。</li><li><strong>√</strong>。红表笔接正极/火线,黑表笔接负极/零线。</li></ol></details>',20)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
